hooks.command:
node -e "
const p = process.env.TOOL_INPUT_FILE_PATH || '';
const svcMap = {
  'backend-services/api-gateway':          'api-gateway',
  'backend-services/catalog-service':       'catalog-service',
  'backend-services/inventory-service':     'inventory-service',
  'backend-services/order-service':         'order-service',
  'backend-services/order-processing':      'order-processing-service',
  'backend-services/user-service':          'user-service',
  'backend-services/aggregator-service':    'aggregator-service',
  'backend-services/discovery-service':     'discovery-service',
  'python-services/mcp-server':             'mcp-server',
  'python-services/notification-service':   'notification-service',
  'frontend':                               'frontend',
  'infrastructure/keycloak':                'keycloak',
  'docker-compose.yml':                     'ALL'
};
const match = Object.entries(svcMap).find(([k]) => p.replace(/\\\\/g,'/').includes(k));
if (match) {
  const svc = match[1];
  if (svc === 'ALL') {
    console.log('\n💡 docker-compose.yml changed — restart affected services:\n   docker-compose up -d');
  } else {
    console.log('\n💡 ' + svc + ' source changed — rebuild to apply:\n   docker-compose up -d --build ' + svc);
  }
}
"
